/* The National Ledger — design system.
   Almanac/ledger look: warm paper, ink navy, a restrained flag-red accent and brass.
   Serif display (Georgia stack) over a system sans body; no webfonts, no network. */

:root {
  --paper: #f4efe4;
  --paper-deep: #ece5d3;
  --card: #fdfaf2;
  --ink: #1e2a3a;
  --ink-soft: #51606f;
  --line: #ddd3bd;
  --line-soft: #e9e1ce;
  --navy: #1f3a5f;
  --red: #a63a2f;
  --gold: #a67c1f;
  --blue: #2e5d8a;
  --green: #3f7d5a;
  --plum: #6e4a72;
  --serif: Georgia, 'Iowan Old Style', 'Times New Roman', serif;
  --sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --mono: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.55;
  /* faint ledger rule in the page background */
  background-image: repeating-linear-gradient(to bottom, transparent 0 30px, rgba(31,58,95,.035) 30px 31px);
}

/* ---------- masthead ---------- */
.masthead { background: var(--card); border-bottom: 1px solid var(--line); }
.stripe { display: flex; height: 5px; }
.stripe i { flex: 1; }
.stripe i:nth-child(odd) { background: var(--red); }
.stripe i:nth-child(even) { background: var(--card); }
.stripe i:nth-child(5) { background: var(--navy); }

.masthead-row {
  max-width: 1160px; margin: 0 auto; padding: 14px 20px 10px;
  display: flex; align-items: center; gap: 18px; flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 12px; text-decoration: none; color: var(--navy); }
.emblem { width: 44px; height: 44px; flex: none; }
.brand-text { display: flex; flex-direction: column; }
.brand-text strong {
  font-family: var(--serif); font-size: 26px; font-weight: 700;
  letter-spacing: .2px; line-height: 1.05; color: var(--ink);
}
.brand-text small {
  font-size: 11.5px; letter-spacing: 2.6px; text-transform: uppercase;
  color: var(--red); font-weight: 700; margin-top: 3px;
}
.tagline {
  margin: 0 0 0 auto; max-width: 380px; text-align: right;
  color: var(--ink-soft); font-size: 13.5px; line-height: 1.45;
  border-right: 3px solid var(--gold); padding-right: 12px;
}

/* ---------- nav ---------- */
.nav {
  max-width: 1160px; margin: 0 auto; padding: 0 20px 12px;
  display: flex; gap: 8px; flex-wrap: wrap;
  scrollbar-width: none;
}
.nav::-webkit-scrollbar { display: none; }
.nav a {
  display: inline-block; padding: 7px 14px 6px;
  border: 1px solid var(--line); border-radius: 999px;
  background: var(--paper); color: var(--navy);
  font-size: 13.5px; font-weight: 600; letter-spacing: .2px;
  text-decoration: none; white-space: nowrap;
}
.nav a:hover { border-color: var(--navy); }
.nav a[aria-current="page"] {
  background: var(--navy); border-color: var(--navy); color: #fff;
}
.nav a .dot { color: var(--gold); margin-right: 5px; }

/* ---------- page frame ---------- */
.page { max-width: 1160px; margin: 0 auto; padding: 20px 20px 40px; }

.kicker {
  font-size: 12px; font-weight: 800; letter-spacing: 2.4px;
  text-transform: uppercase; color: var(--red); margin: 0 0 6px;
}
.page h1 {
  font-family: var(--serif); font-size: 38px; line-height: 1.1;
