.kpi-grid {
  display: grid; gap: 12px; margin: 4px 0 26px;
  grid-template-columns: repeat(auto-fill, minmax(178px, 1fr));
}
.kpi {
  background: var(--card); border: 1px solid var(--line); border-radius: 10px;
