.src::before { content: "◦ "; color: var(--gold); }

/* ---------- cards & charts ---------- */
.card {
  background: var(--card); border: 1px solid var(--line);
  border-radius: 10px; padding: 18px 20px 14px; margin-bottom: 18px;
}
.card-head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; margin-bottom: 4px; }
.card-head h3 { margin: 0; font-family: var(--serif); font-size: 19px; }
.card-head .card-note { font-size: 12.5px; color: var(--ink-soft); margin-left: auto; }
.chart-wrap { margin: 8px 0 4px; }
.chart-wrap svg { display: block; width: 100%; height: auto; }
.chart-foot { display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; font-size: 12px; color: var(--ink-soft); padding-top: 6px; border-top: 1px dashed var(--line); margin-top: 6px; }

/* segmented control on chart cards */
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 7px; overflow: hidden; margin-left: auto; }
.seg button {
  appearance: none; border: 0; background: var(--paper); color: var(--navy);
  font: 600 12px/1 var(--sans); padding: 7px 12px; cursor: pointer; border-right: 1px solid var(--line);
}
