.seg button[aria-pressed="true"] { background: var(--navy); color: #fff; }
.seg button:hover:not([aria-pressed="true"]) { background: var(--paper-deep); }

/* ---------- tables ---------- */
.tbl-wrap { overflow-x: auto; margin: 6px 0 4px; }
table.tbl { width: 100%; border-collapse: collapse; font-size: 14px; }
.tbl th {
  text-align: left; font-size: 11.5px; letter-spacing: 1px; text-transform: uppercase;
  color: var(--ink-soft); border-bottom: 2px solid var(--navy); padding: 7px 10px 6px 0;
}
.tbl td { padding: 7px 10px 7px 0; border-bottom: 1px solid var(--line-soft); vertical-align: top; }
.tbl tr:last-child td { border-bottom: 0; }
.tbl td.num, .tbl th.num { text-align: right; font-variant-numeric: tabular-nums; }
.tbl td .row-note { display: block; font-size: 11.5px; color: var(--ink-soft); }

/* ---------- prose & misc ---------- */
.prose { max-width: 800px; }
.prose p { color: var(--ink-soft); font-size: 15px; }
.prose p strong, .prose li strong { color: var(--ink); }
.prose ul { margin: 6px 0 12px; padding-left: 20px; color: var(--ink-soft); font-size: 15px; }
.prose li { margin-bottom: 6px; }
.callout {
  border-left: 4px solid var(--gold); background: #faf4e3;
  padding: 12px 16px; border-radius: 0 8px 8px 0; margin: 14px 0;
