.index-card:hover { border-color: var(--navy); }
.index-card .i-title { font-family: var(--serif); font-size: 18px; font-weight: 700; color: var(--navy); }
.index-card .i-stat { font-size: 22px; font-family: var(--serif); color: var(--ink); margin: 4px 0 1px; }
.index-card .i-desc { font-size: 12.5px; color: var(--ink-soft); }

/* legend for donut */
.legend { display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 12.5px; color: var(--ink-soft); margin-top: 6px; }
.legend .sw { display: inline-block; width: 11px; height: 11px; border-radius: 3px; margin-right: 6px; vertical-align: -1px; }
.legend b { color: var(--ink); }

/* svg chart text */
svg .ax { font-family: var(--sans); font-size: 12px; fill: var(--ink-soft); }
svg .axv { font-family: var(--sans); font-size: 12.5px; font-weight: 700; fill: var(--ink); }
svg .big { font-family: var(--serif); font-weight: 700; fill: var(--ink); }

/* ---------- footer ---------- */
.colophon {
  border-top: 1px solid var(--line); background: var(--card);
  padding: 20px; margin-top: 20px;
}
.colophon p { max-width: 1160px; margin: 0 auto 8px; font-size: 12.5px; color: var(--ink-soft); }

/* ---------- responsive ---------- */
@media (max-width: 900px) {
  .grid-2 { grid-template-columns: 1fr; }
  .page h1 { font-size: 30px; }
}
@media (max-width: 620px) {
  .masthead-row { padding: 10px 14px 6px; gap: 8px; }
  .emblem { width: 38px; height: 38px; }
  .brand-text strong { font-size: 21px; }
  .brand-text small { font-size: 10px; letter-spacing: 2px; }
  .tagline { display: none; }
  .nav { flex-wrap: nowrap; overflow-x: auto; padding: 0 14px 10px; -webkit-overflow-scrolling: touch; }
  .nav a { padding: 6px 12px 5px; font-size: 12.5px; }
  .page { padding: 18px 14px 30px; }
  .page h1 { font-size: 27px; }
  .lede { font-size: 15px; }
  .kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 8px; }
  .kpi .k-value { font-size: 25px; }
  .card { padding: 14px 14px 10px; }
  .card-head .card-note { margin-left: 0; width: 100%; }
  .seg { margin-left: 0; }
}
